<div class="module-intro"><div><span class="eyebrow">CONFIGURAÇÃO INSTITUCIONAL</span><h2>ADM · Administração do sistema</h2><p>Perfis, permissões, identidade institucional e auditoria.</p></div></div>
<section class="panel"><div class="section-heading"><div><h3>Configurações gerais</h3><p>Parâmetros exibidos e utilizados pela aplicação.</p></div></div><form method="post" action="<?= e($baseUrl) ?>/adm/config" class="form-grid"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><?php foreach(['institution_name'=>'Nome institucional','department_name'=>'Nome do departamento','contact_email'=>'E-mail de contato','contact_phone'=>'Telefone institucional','logo_path'=>'Caminho do logotipo','protocol_prefix'=>'Prefixo dos protocolos','upload_max_mb'=>'Limite de upload (MB)'] as $key=>$label): ?><label><?= e($label) ?><input name="<?= $key ?>" value="<?= e($settings[$key]??($key==='upload_max_mb'?'8':($key==='protocol_prefix'?'SIN':''))) ?>"></label><?php endforeach; ?><div class="full"><button class="btn primary">Salvar configurações</button></div></form></section>
<section class="panel"><div class="section-heading"><div><h3>Perfis e permissões</h3><p>Defina quais ações cada perfil poderá executar.</p></div></div><?php foreach($roles as $role): ?><details class="role-editor"><summary><b><?= e($role['name']) ?></b><span><?= (int)$role['permission_count'] ?> permissões</span></summary><form method="post" action="<?= e($baseUrl) ?>/adm/perfil"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input type="hidden" name="role_id" value="<?= (int)$role['id'] ?>"><div class="form-grid"><label>Nome do perfil<input name="name" value="<?= e($role['name']) ?>" required></label><label>Descrição<input name="description" value="<?= e($role['description']??'') ?>"></label></div><div class="permission-grid"><?php foreach($permissions as $p): ?><label><input type="checkbox" name="permission_ids[]" value="<?= (int)$p['id'] ?>" <?= in_array((int)$p['id'],$rolePermissions[$role['id']]??[],true)?'checked':'' ?>><span><b><?= e($p['label']) ?></b><small><?= e($p['module']) ?></small></span></label><?php endforeach; ?></div><button class="btn primary">Salvar perfil</button></form></details><?php endforeach; ?><details class="role-editor"><summary><b>Criar novo perfil</b></summary><form method="post" action="<?= e($baseUrl) ?>/adm/perfil"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><div class="form-grid"><label>Nome<input name="name" required></label><label>Descrição<input name="description"></label></div><div class="permission-grid"><?php foreach($permissions as $p): ?><label><input type="checkbox" name="permission_ids[]" value="<?= (int)$p['id'] ?>"><span><b><?= e($p['label']) ?></b><small><?= e($p['module']) ?></small></span></label><?php endforeach; ?></div><button class="btn primary">Criar perfil</button></form></details></section>
<section class="panel"><div class="section-heading"><div><h3>Auditoria recente</h3><p>Últimos 100 eventos registrados.</p></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Usuário</th><th>Ação</th><th>Módulo</th><th>Registro</th><th>IP</th></tr></thead><tbody><?php foreach($audit as $a): ?><tr><td><?= date('d/m/Y H:i:s',strtotime($a['created_at'])) ?></td><td><?= e($a['user_name']??'Sistema') ?></td><td><?= e($a['action']) ?></td><td><?= e($a['module']) ?></td><td><?= e($a['record_id']??'—') ?></td><td><?= e($a['ip_address']??'—') ?></td></tr><?php endforeach; ?></tbody></table></div></section>